"use client";

import { useMemo, useRef, useState, type ReactNode } from "react";
import {
  DataGridBody,
  DataGridHeader,
  DataGridProvider,
  DataGridRoot,
  defineColumns,
  type CellClickCtx,
  type GridCommand,
  type Keymap,
} from "@/registry/default/components/data-grid/data-grid";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 150, flex: 2 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 180, flex: 2 },
  { id: "role", header: "Role", accessorKey: "role", type: "text", width: 100, flex: 1 },
  { id: "active", header: "Active", accessorKey: "active", type: "checkbox", width: 70, flex: 1 },
] as const);

const keymap = { openRow: ["mod+shift+Enter"] } as Keymap;

export default function DataGridDetailPanelDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(30), []);
  const rowsById = useMemo(() => new Map(rows.map((row) => [row.id, row])), [rows]);
  const [open, setOpen] = useState(false);
  const [rowId, setRowId] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const row = rowId === null ? undefined : rowsById.get(rowId);

  const close = () => {
    setOpen(false);
    containerRef.current?.querySelector<HTMLElement>('[role="grid"]')?.focus();
  };

  const commands = useMemo<Record<string, GridCommand<DemoRow>>>(
    () => ({
      openRow: {
        label: "Open row",
        when: (ctx) => ctx.row !== undefined,
        run: () => setOpen(true),
      },
    }),
    [],
  );

  const openFromClick = (ctx: CellClickCtx<DemoRow, unknown>) => {
    if (ctx.columnId !== "active") setOpen(true);
  };

  return (
    <div className="flex flex-col gap-2">
      <p className="m-0 text-sm text-muted-foreground">
        Click a cell, or press Ctrl+Shift+Enter on the active cell, to show its row. The panel follows the active
        cell while you move with the arrow keys. Escape closes it when focus is inside the panel.
      </p>
      <div ref={containerRef} className="relative overflow-hidden">
        <DataGridProvider
          data={rows}
          columns={columns}
          getRowId={(r) => r.id}
          onCellClick={openFromClick}
          onActiveCellChange={(next) => setRowId(next?.rowId ?? null)}
          commands={commands}
          keymap={keymap}
        >
          <DataGridRoot className="h-[360px]">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
        <aside
          role="complementary"
          aria-label="Row details"
          inert={!open}
          data-open={open}
          onKeyDown={(event) => {
            if (event.key === "Escape") close();
          }}
          className="absolute inset-y-0 right-0 flex w-64 flex-col gap-3 border-l bg-background p-4 shadow-md transition-transform duration-200 motion-reduce:transition-none data-[open=false]:translate-x-full"
        >
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <h3 className="m-0 truncate text-sm font-semibold">{row?.name ?? "No row"}</h3>
              <p className="m-0 truncate text-xs text-muted-foreground">{row?.email}</p>
            </div>
            <button
              type="button"
              onClick={close}
              aria-label="Close details"
              className="rounded px-2 text-sm text-muted-foreground hover:bg-muted"
            >
              ×
            </button>
          </div>
          {row ? (
            <dl className="m-0 grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-sm">
              <dt className="text-muted-foreground">Role</dt>
              <dd className="m-0">{row.role}</dd>
              <dt className="text-muted-foreground">Age</dt>
              <dd className="m-0">{row.age}</dd>
              <dt className="text-muted-foreground">Joined</dt>
              <dd className="m-0">{row.joined}</dd>
            </dl>
          ) : (
            <p className="m-0 text-sm text-muted-foreground">Select a cell to see its row.</p>
          )}
        </aside>
      </div>
      <button
        type="button"
        onClick={() => (open ? close() : setOpen(true))}
        aria-expanded={open}
        className="self-start rounded border px-3 py-1 text-sm hover:bg-muted"
      >
        Details
      </button>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
